/**
 * Prototype flow registry
 *
 * Add an entry here for every flow you create under app/prototypes/<slug>/.
 * The index page reads from this list — no other wiring needed.
 */

export type FlowMeta = {
  slug: string
  name: string
  description: string
  /** What the flow exercises in the design system */
  exercises: string[]
  /** Optional tag — "in-progress" | "stable" | "experimental" */
  status?: "in-progress" | "stable" | "experimental"
}

export const flows: FlowMeta[] = [
  {
    slug: "tabby",
    name: "Tabby — iOS onboarding",
    description:
      "Multi-step onboarding clone: splash, country picker, marketing carousel, phone + OTP, PIN, trust device, privacy, and a stores home.",
    exercises: ["Button", "Input", "Label", "Card", "Dialog", "Alert", "Badge"],
    status: "in-progress",
  },
  {
    slug: "wise-home",
    name: "Wise — Home screen",
    description:
      "Mobile banking home screen: balance cards, transaction feed, promotional interest card, and bottom tab navigation — based on the Wise app design.",
    exercises: ["Button", "Card", "NavBar", "Badge"],
    status: "stable",
  },
]

import Link from "next/link"
import { flows } from "./_shared/flowRegistry"
import { Card, CardHeader, CardTitle, CardDescription, CardContent, CardFooter } from "@atlas/ui-web/compositions/Card/Card"
import { Badge } from "@atlas/ui-web/primitives/Badge/Badge"

export default function PrototypesIndex() {
  return (
    <div
      style={{
        minHeight: "100vh",
        background: "var(--atlas-background)",
        color: "var(--atlas-foreground)",
        fontFamily: "var(--atlas-font-sans)",
      }}
    >
      <div
        style={{
          maxWidth: 880,
          margin: "0 auto",
          padding: "var(--atlas-spacing-12) var(--atlas-spacing-6)",
          display: "flex",
          flexDirection: "column",
          gap: "var(--atlas-spacing-8)",
        }}
      >
        <div>
          <Link
            href="/"
            style={{
              fontSize: "var(--atlas-font-size-sm)",
              color: "var(--atlas-foreground-muted)",
              textDecoration: "none",
            }}
          >
            ← Sandbox
          </Link>
          <h1
            style={{
              margin: "var(--atlas-spacing-3) 0 var(--atlas-spacing-2)",
              fontSize: "var(--atlas-font-size-3xl)",
              fontWeight: 700,
            }}
          >
            Prototype flows
          </h1>
          <p
            style={{
              margin: 0,
              color: "var(--atlas-foreground-muted)",
              fontSize: "var(--atlas-font-size-base)",
              maxWidth: 640,
            }}
          >
            Interactive flows built from Atlas components. Each flow is a small,
            self-contained app under <code>app/prototypes/&lt;slug&gt;</code>.
          </p>
        </div>

        <div
          style={{
            display: "grid",
            gridTemplateColumns: "repeat(auto-fill, minmax(280px, 1fr))",
            gap: "var(--atlas-spacing-4)",
          }}
        >
          {flows.map((flow) => (
            <Link
              key={flow.slug}
              href={`/prototypes/${flow.slug}`}
              style={{ textDecoration: "none", color: "inherit" }}
            >
              <Card interactive variant="elevated">
                <CardHeader>
                  <CardTitle>{flow.name}</CardTitle>
                  <CardDescription>{flow.description}</CardDescription>
                </CardHeader>
                <CardContent>
                  <div
                    style={{
                      display: "flex",
                      flexWrap: "wrap",
                      gap: "var(--atlas-spacing-1_5)",
                    }}
                  >
                    {flow.exercises.map((c) => (
                      <Badge key={c} size="sm" variant="secondary">
                        {c}
                      </Badge>
                    ))}
                  </div>
                </CardContent>
                {flow.status && (
                  <CardFooter>
                    <Badge
                      size="sm"
                      variant={
                        flow.status === "stable"
                          ? "success"
                          : flow.status === "experimental"
                          ? "warning"
                          : "info"
                      }
                      dot
                    >
                      {flow.status}
                    </Badge>
                  </CardFooter>
                )}
              </Card>
            </Link>
          ))}
        </div>
      </div>
    </div>
  )
}

"use client"

import React from "react"
import Link from "next/link"
import { Button } from "@atlas/ui-web/primitives/Button/Button"
import { PhoneFrame } from "./PhoneFrame"
import { StepProgress } from "./StepProgress"

/**
 * FlowShell — outer page chrome for any prototype flow.
 *
 * Renders the page background, a small header with the flow title + a
 * "back to prototypes" link, an optional step progress bar, and the phone
 * frame that wraps the active screen.
 */
export function FlowShell({
  title,
  step,
  totalSteps,
  onReset,
  showProgress = true,
  phoneBackground,
  statusBarTint,
  homeIndicatorTint,
  children,
}: {
  title: string
  step: number
  totalSteps: number
  onReset?: () => void
  showProgress?: boolean
  phoneBackground?: string
  statusBarTint?: "dark" | "light"
  homeIndicatorTint?: "dark" | "light"
  children: React.ReactNode
}) {
  return (
    <div
      style={{
        minHeight: "100vh",
        background: "var(--atlas-background-subtle)",
        color: "var(--atlas-foreground)",
        fontFamily: "var(--atlas-font-sans)",
        display: "flex",
        flexDirection: "column",
      }}
    >
      {/* Page header — outside the phone */}
      <header
        style={{
          display: "flex",
          alignItems: "center",
          justifyContent: "space-between",
          padding: "var(--atlas-spacing-4) var(--atlas-spacing-6)",
          borderBottom: "1px solid var(--atlas-border)",
          background: "var(--atlas-background)",
        }}
      >
        <div style={{ display: "flex", alignItems: "center", gap: "var(--atlas-spacing-3)" }}>
          <Link
            href="/prototypes"
            style={{
              fontSize: "var(--atlas-font-size-sm)",
              color: "var(--atlas-foreground-muted)",
              textDecoration: "none",
            }}
          >
            ← Prototypes
          </Link>
          <span style={{ color: "var(--atlas-border-strong)" }}>/</span>
          <strong style={{ fontSize: "var(--atlas-font-size-sm)" }}>{title}</strong>
        </div>
        <div style={{ display: "flex", alignItems: "center", gap: "var(--atlas-spacing-3)" }}>
          <span
            style={{
              fontSize: "var(--atlas-font-size-xs)",
              color: "var(--atlas-foreground-muted)",
            }}
          >
            Step {step + 1} of {totalSteps}
          </span>
          {onReset && (
            <Button size="sm" variant="ghost" onClick={onReset}>
              Reset
            </Button>
          )}
        </div>
      </header>

      {/* Progress bar — full width, slim, under the header */}
      {showProgress && (
        <div style={{ padding: "var(--atlas-spacing-2) var(--atlas-spacing-6)" }}>
          <StepProgress total={totalSteps} current={step} />
        </div>
      )}

      {/* Phone frame */}
      <main
        style={{
          flex: 1,
          display: "flex",
          alignItems: "center",
          justifyContent: "center",
          padding: "var(--atlas-spacing-8) var(--atlas-spacing-4)",
        }}
      >
        <PhoneFrame
          background={phoneBackground}
          statusBarTint={statusBarTint}
          homeIndicatorTint={homeIndicatorTint}
        >
          {children}
        </PhoneFrame>
      </main>
    </div>
  )
}

