#!/usr/bin/env node
/**
 * Atlas Design System — Token Governance Lint
 *
 * Walks packages/ui-web/src/ and app/ for hardcoded colour/spacing values
 * that should reference --atlas-* CSS custom properties instead.
 *
 * Rules:
 *   1. No hex colour literals (#abc, #aabbcc, #aabbccdd)
 *   2. No rgb() / rgba() calls (outside packages/tokens/)
 *   3. No oklch() calls (outside packages/tokens/)
 *   4. No hsl() / hsla() calls (outside packages/tokens/)
 *
 * Allow-list:
 *   - Lines containing "token-lint-disable-next-line" suppress the NEXT line only.
 *   - Files in packages/tokens/ are always skipped.
 *   - Test files (*.test.*) and governance scripts are skipped.
 *   - Storybook / example files are skipped.
 *
 * Usage:
 *   node packages/governance/token-lint.mjs
 *   node packages/governance/token-lint.mjs --fix   (future — not yet implemented)
 *
 * Exit codes:
 *   0  — no violations
 *   1  — violations found
 */

import fs from "fs"
import path from "path"
import { fileURLToPath } from "url"

const __dirname = path.dirname(fileURLToPath(import.meta.url))
const ROOT = path.resolve(__dirname, "../..")

// ─── Config ──────────────────────────────────────────────────────────────────

const SCAN_DIRS = [
  path.join(ROOT, "packages/ui-web/src"),
  path.join(ROOT, "app"),
]

const SKIP_DIRS = new Set([
  "node_modules",
  ".next",
  ".git",
  "packages/tokens",
  "packages/governance",
])

const SKIP_FILE_PATTERNS = [
  /\.test\.[tj]sx?$/,
  /\.spec\.[tj]sx?$/,
  /\.stories\.[tj]sx?$/,
  /vitest\.config/,
]

const SCAN_EXTENSIONS = new Set([".ts", ".tsx", ".css"])

// ─── Rules ───────────────────────────────────────────────────────────────────

const RULES = [
  {
    id: "no-hex-color",
    description: "Hardcoded hex colour — use an --atlas-* token instead",
    // Matches #RGB, #RRGGBB, #RRGGBBAA — but not CSS ID selectors or comments
    pattern: /(?<![/]{2}[^\n]*)(?:^|[\s:,(])(#[0-9a-fA-F]{3,8})\b/,
    // Skip lines that are pure CSS selectors (e.g. #app { )
    skip: (line) => /^#[\w-]+\s*[{,]/.test(line.trim()),
  },
  {
    id: "no-rgb",
    description: "Hardcoded rgb()/rgba() — use an --atlas-* token instead",
    pattern: /\brgba?\s*\(/,
    skip: () => false,
  },
  {
    id: "no-oklch-raw",
    description: "Raw oklch() outside tokens package — use an --atlas-* token instead",
    pattern: /\boklch\s*\(/,
    // Allow oklch(1 0 0) / oklch(0 0 0) — achromatic white/black anchors used
    // legitimately inside color-mix() as neutral mix targets. Any chroma (C > 0)
    // would indicate a hardcoded brand colour that should become a token.
    skip: (line) => /\bcolor-mix\(in\s+oklch,/.test(line) &&
                    /oklch\(\s*[01]\.?\d*\s+0\s+0\s*\)/.test(line),
  },
  {
    id: "no-hsl",
    description: "Hardcoded hsl()/hsla() — use an --atlas-* token instead",
    pattern: /\bhsla?\s*\(/,
    skip: () => false,
  },
]

// ─── Walker ──────────────────────────────────────────────────────────────────

function* walkFiles(dir) {
  if (!fs.existsSync(dir)) return
  for (const entry of fs.readdirSync(dir, { withFileTypes: true })) {
    const fullPath = path.join(dir, entry.name)
    if (entry.isDirectory()) {
      const rel = path.relative(ROOT, fullPath)
      if ([...SKIP_DIRS].some((d) => rel.startsWith(d) || entry.name === d)) continue
      yield* walkFiles(fullPath)
    } else if (entry.isFile()) {
      const ext = path.extname(entry.name)
      if (!SCAN_EXTENSIONS.has(ext)) continue
      if (SKIP_FILE_PATTERNS.some((p) => p.test(entry.name))) continue
      yield fullPath
    }
  }
}

// ─── Lint ────────────────────────────────────────────────────────────────────

const violations = []

for (const dir of SCAN_DIRS) {
  for (const filePath of walkFiles(dir)) {
    const rel = path.relative(ROOT, filePath)
    const lines = fs.readFileSync(filePath, "utf8").split("\n")

    let suppressNext = false
    for (let i = 0; i < lines.length; i++) {
      const line = lines[i]
      const lineNo = i + 1

      if (line.includes("token-lint-disable-next-line")) {
        suppressNext = true
        continue
      }

      if (suppressNext) {
        suppressNext = false
        continue
      }

      for (const rule of RULES) {
        if (rule.skip(line)) continue
        if (rule.pattern.test(line)) {
          violations.push({ file: rel, line: lineNo, rule: rule.id, text: line.trim() })
        }
      }
    }
  }
}

// ─── Report ──────────────────────────────────────────────────────────────────

if (violations.length === 0) {
  console.log("✅ Token lint: 0 violations")
  process.exit(0)
} else {
  console.error(`❌ Token lint: ${violations.length} violation${violations.length === 1 ? "" : "s"} found\n`)
  let lastFile = null
  for (const v of violations) {
    if (v.file !== lastFile) {
      console.error(`  ${v.file}`)
      lastFile = v.file
    }
    console.error(`    [${v.rule}] line ${v.line}: ${v.text.slice(0, 120)}`)
  }
  console.error(`
To suppress a single line, add a comment on the preceding line:
  /* token-lint-disable-next-line */
`)
  process.exit(1)
}

"use client"

/**
 * Atlas Dialog — modal / sheet / drawer surface
 *
 * Powered by @radix-ui/react-dialog for:
 *   - focus trap (Tab / Shift+Tab cycles inside content)
 *   - scroll lock (body scroll disabled while open)
 *   - keyboard dismiss (Escape key)
 *   - aria-modal, aria-labelledby, aria-describedby wiring
 *   - click-outside dismiss via onInteractOutside
 *
 * Variants:  modal (default) | sheet | drawer
 * Sizes:     sm | md | lg | xl | full
 *
 * Compound API:
 *   <Dialog open onOpenChange={...}>
 *     <DialogTrigger asChild><Button>Open</Button></DialogTrigger>
 *     <DialogContent variant="modal" size="md">
 *       <DialogHeader>
 *         <DialogTitle>…</DialogTitle>
 *         <DialogDescription>…</DialogDescription>
 *       </DialogHeader>
 *       <DialogBody>…</DialogBody>
 *       <DialogFooter>
 *         <DialogClose asChild><Button variant="outline">Cancel</Button></DialogClose>
 *         <Button>Confirm</Button>
 *       </DialogFooter>
 *     </DialogContent>
 *   </Dialog>
 *
 * Accessibility:
 *   - role="dialog" + aria-modal="true" via Radix
 *   - aria-labelledby → DialogTitle id (Radix auto-wires)
 *   - aria-describedby → DialogDescription id (Radix auto-wires)
 *   - Initial focus → first focusable element inside DialogContent
 *   - Escape → closes (unless closeOnEscape=false)
 *   - Focus returns to trigger on close
 *
 * Token compliance: all values via semantic tokens in Dialog.module.css.
 */

import React, { useId } from "react"
import * as RadixDialog from "@radix-ui/react-dialog"
import styles from "./Dialog.module.css"

/* ── Helpers ────────────────────────────────────────────────────── */

function cx(...classes: (string | false | null | undefined)[]): string {
  return classes.filter(Boolean).join(" ")
}

/* ── Types ──────────────────────────────────────────────────────── */

export type DialogVariant = "modal" | "sheet" | "drawer"
export type DialogSize    = "sm" | "md" | "lg" | "xl" | "full"
export type DialogSide    = "start" | "end"

/* ── Dialog root ────────────────────────────────────────────────── */
/*
 * Thin wrapper around Radix Root.
 * Supports both controlled (open + onOpenChange) and uncontrolled (defaultOpen).
 */

export interface DialogProps {
  open?:          boolean
  defaultOpen?:   boolean
  /** Called with next open state; use setOpen directly (receives boolean) */
  onOpenChange?:  (open: boolean) => void
  /** @deprecated — use onOpenChange instead */
  onClose?:       () => void
  children?:      React.ReactNode
}

export function Dialog({ open, defaultOpen, onOpenChange, onClose, children }: DialogProps) {
  const handleChange = (next: boolean) => {
    onOpenChange?.(next)
    if (!next) onClose?.()
  }

  return (
    <RadixDialog.Root
      open={open}
      defaultOpen={defaultOpen}
      onOpenChange={handleChange}
    >
      {children}
    </RadixDialog.Root>
  )
}

/* ── DialogTrigger ──────────────────────────────────────────────── */

export interface DialogTriggerProps {
  asChild?:  boolean
  children?: React.ReactNode
}

export function DialogTrigger({ asChild = true, children }: DialogTriggerProps) {
  return (
    <RadixDialog.Trigger asChild={asChild}>
      {children}
    </RadixDialog.Trigger>
  )
}

/* ── DialogContent ──────────────────────────────────────────────── */
/*
 * Renders: Portal → Overlay → Content surface.
 * Variant / size classes applied here.
 * Sheet gets the drag handle at the top.
 */

export interface DialogContentProps {
  variant?:             DialogVariant
  size?:                DialogSize
  /** Drawer only: which edge to slide from */
  side?:                DialogSide
  id?:                  string
  closeOnEscape?:       boolean
  closeOnOverlayClick?: boolean
  className?:           string
  children?:            React.ReactNode
}

export function DialogContent({
  variant             = "modal",
  size                = "md",
  side                = "end",
  id,
  closeOnEscape       = true,
  closeOnOverlayClick = true,
  className,
  children,
}: DialogContentProps) {
  const contentClasses = cx(
    styles.content,
    styles[variant],
    size !== "md" && styles[size],
    className,
  )

  return (
    <RadixDialog.Portal>
      {/* Overlay */}
      <RadixDialog.Overlay className={styles.overlay} />

      {/* Content surface */}
      <RadixDialog.Content
        id={id}
        className={contentClasses}
        data-side={variant === "drawer" ? side : undefined}
        onEscapeKeyDown={(e) => { if (!closeOnEscape) e.preventDefault() }}
        onInteractOutside={(e) => { if (!closeOnOverlayClick) e.preventDefault() }}
      >
        {/* Drag handle — sheet only; visual affordance only (FIX BUG-037 + BUG-066)
             Not interactive: close is via header × button or swipe gesture.
             aria-hidden prevents screen readers from announcing the decoration. */}
        {variant === "sheet" && (
          <div className={styles.dragHandle} aria-hidden="true" />
        )}

        {children}
      </RadixDialog.Content>
    </RadixDialog.Portal>
  )
}

/* ── DialogHeader ───────────────────────────────────────────────── */
/*
 * Horizontal row: [main slot] [close button].
 * showClose=true by default — renders a RadixDialog.Close button.
 * Pass showClose=false if you want no built-in × (or use DialogClose yourself).
 */

export interface DialogHeaderProps {
  showClose?: boolean
  /** @deprecated — close is now handled by Radix; prop accepted but ignored */
  onClose?:   () => void
  className?: string
  children?:  React.ReactNode
}

export function DialogHeader({ showClose = true, className, children }: DialogHeaderProps) {
  return (
    <div className={cx(styles.header, className)}>
      <div className={styles.headerMain}>
        {children}
      </div>

      {showClose && (
        <RadixDialog.Close
          className={styles.closeBtn}
          aria-label="Close dialog"
        >
          ✕
        </RadixDialog.Close>
      )}
    </div>
  )
}

/* ── DialogTitle ────────────────────────────────────────────────── */
/*
 * Wrapped in RadixDialog.Title for aria-labelledby wiring.
 * Required for accessibility — every dialog must have a title.
 */

export interface DialogTitleProps {
  className?: string
  children?:  React.ReactNode
}

export function DialogTitle({ className, children }: DialogTitleProps) {
  return (
    <RadixDialog.Title className={cx(styles.title, className)}>
      {children}
    </RadixDialog.Title>
  )
}

/* ── DialogDescription ──────────────────────────────────────────── */
/*
 * Wrapped in RadixDialog.Description for aria-describedby wiring.
 */

export interface DialogDescriptionProps {
  className?: string
  children?:  React.ReactNode
}

export function DialogDescription({ className, children }: DialogDescriptionProps) {
  return (
    <RadixDialog.Description className={cx(styles.description, className)}>
      {children}
    </RadixDialog.Description>
  )
}

/* ── DialogBody ─────────────────────────────────────────────────── */

export interface DialogBodyProps {
  className?: string
  children?:  React.ReactNode
}

export function DialogBody({ className, children }: DialogBodyProps) {
  return (
    <div className={cx(styles.body, className)}>
      {children}
    </div>
  )
}

/* ── DialogFooter ───────────────────────────────────────────────── */

export interface DialogFooterProps {
  justify?:   "start" | "between" | "end"
  className?: string
  children?:  React.ReactNode
}

export function DialogFooter({ justify = "end", className, children }: DialogFooterProps) {
  const justifyClass =
    justify === "between" ? styles.footerBetween :
    justify === "start"   ? styles.footerStart   :
    styles.footerEnd

  return (
    <div className={cx(styles.footer, justifyClass, className)}>
      {children}
    </div>
  )
}

/* ── DialogClose ────────────────────────────────────────────────── */
/*
 * Wraps any element to close the dialog on click.
 * Use asChild=true (default) to render the child element as the trigger.
 */

export interface DialogCloseProps {
  asChild?:  boolean
  children?: React.ReactNode
}

export function DialogClose({ asChild = true, children }: DialogCloseProps) {
  return (
    <RadixDialog.Close asChild={asChild}>
      {children}
    </RadixDialog.Close>
  )
}

"use client"

/**
 * Atlas Input — single-line text entry
 *
 * Variants:  default | filled | unstyled
 * Sizes:     sm | md | lg
 * States:    default · hover · focus-visible · disabled · readonly · error · loading
 *
 * Slots:
 *   leadingIcon  — icon at inline-start
 *   trailingIcon — icon at inline-end (hidden while loading; spinner shown instead)
 *   prefix       — affix text at inline-start (e.g. "$")
 *   suffix       — affix text at inline-end (e.g. ".com")
 *
 * Accessibility:
 *   - aria-invalid="true" when invalid prop is set
 *   - aria-required passed through from caller
 *   - aria-describedby wired by caller (to HelperText / ErrorText)
 *   - Focus ring via CSS :focus-visible; never suppressed
 *
 * Logical properties and prefers-reduced-motion handled in Input.module.css.
 */

import React from "react"
import styles from "./Input.module.css"

/* ── Types ──────────────────────────────────────────────────── */

export type InputVariant = "default" | "filled" | "unstyled"
export type InputSize = "sm" | "md" | "lg"

export interface InputProps
  extends Omit<React.InputHTMLAttributes<HTMLInputElement>, "size" | "prefix"> {
  variant?: InputVariant
  size?: InputSize
  /** Marks the field as invalid — sets aria-invalid and switches border to danger colour */
  invalid?: boolean
  /** Shows a loading spinner in the trailing-icon slot */
  loading?: boolean
  /** Icon node rendered at inline-start */
  leadingIcon?: React.ReactNode
  /**
   * Icon node rendered at inline-end.
   * Replaced by a loading spinner when loading=true.
   */
  trailingIcon?: React.ReactNode
  /** Short text affix rendered at inline-start inside the field (e.g. "$") */
  prefix?: React.ReactNode
  /** Short text affix rendered at inline-end inside the field (e.g. ".com") */
  suffix?: React.ReactNode
}

/* ── Component ──────────────────────────────────────────────── */

export function Input({
  variant = "default",
  size = "md",
  invalid = false,
  loading = false,
  leadingIcon,
  trailingIcon,
  prefix,
  suffix,
  disabled,
  readOnly,
  className,
  ...rest
}: InputProps) {
  /*
   * Trailing slot priority:
   *   loading=true  → spinner (trailingIcon hidden to avoid layout shift)
   *   loading=false → trailingIcon (if provided)
   */
  const trailingSlot = loading ? (
    <span className={styles.spinner} aria-hidden="true">
      <span className={styles.spinnerInner} />
    </span>
  ) : (
    trailingIcon
  )

  const hasLeading = !!leadingIcon || !!prefix
  const hasTrailing = !!trailingSlot || !!suffix

  return (
    <div
      className={`${styles.wrapper} ${styles[variant]}`}
      data-leading-icon={hasLeading || undefined}
      data-trailing-icon={hasTrailing || undefined}
      data-prefix={prefix ? true : undefined}
      data-suffix={suffix ? true : undefined}
    >
      {/* Leading icon — mutually exclusive with prefix; icon takes visual priority */}
      {leadingIcon && (
        <span className={`${styles.icon} ${styles.iconLeading}`} aria-hidden="true">
          {leadingIcon}
        </span>
      )}

      {/* Prefix affix text */}
      {!leadingIcon && prefix && (
        <span className={`${styles.affix} ${styles.affixPrefix}`} aria-hidden="true">
          {prefix}
        </span>
      )}

      <input
        {...rest}
        className={`${styles.input} ${styles[size]}${className ? ` ${className}` : ""}`}
        disabled={disabled}
        readOnly={readOnly}
        aria-invalid={invalid || undefined}
      />

      {/* Suffix affix text */}
      {!trailingSlot && suffix && (
        <span className={`${styles.affix} ${styles.affixSuffix}`} aria-hidden="true">
          {suffix}
        </span>
      )}

      {/* Trailing icon or spinner */}
      {trailingSlot && (
        <span className={`${styles.icon} ${styles.iconTrailing}`} aria-hidden="true">
          {trailingSlot}
        </span>
      )}
    </div>
  )
}

"use client"

/**
 * Atlas Card — surface that groups related content
 *
 * Variants:  default | elevated | outlined | filled
 * Sizes:     sm | md | lg
 * States:    default · hover (interactive) · focus-visible (interactive)
 *            · selected · disabled
 *
 * Compound API:
 *   <Card>
 *     <CardHeader leading={<Icon />} action={<Button />}>
 *       <CardTitle>…</CardTitle>
 *       <CardDescription>…</CardDescription>
 *     </CardHeader>
 *     <CardContent>…</CardContent>
 *     <CardFooter justify="between">…</CardFooter>
 *   </Card>
 *
 * Accessibility:
 *   - Non-interactive: <article> (semantic landmark)
 *   - Interactive: <button type="button">, aria-labelledby → CardTitle id (via context)
 *   - Selected: aria-pressed="true" (toggle) or aria-selected (listbox/grid)
 *   - Disabled: aria-disabled, pointer-events suppressed
 *   - Focus ring via CSS :focus-visible on the card root
 *
 * Logical properties and token-only values in Card.module.css.
 */

import React, { createContext, useContext, useId } from "react"
import styles from "./Card.module.css"

/* ── Helpers ─────────────────────────────────────────────────── */

function cx(...classes: (string | false | null | undefined)[]): string {
  return classes.filter(Boolean).join(" ")
}

/* ── Card context ────────────────────────────────────────────── */
/*
 * Passes the auto-generated titleId down to CardTitle so it can
 * self-assign id={titleId}, enabling aria-labelledby from the
 * interactive card root without prop-drilling.
 */

interface CardContextValue {
  titleId: string
}

const CardContext = createContext<CardContextValue | null>(null)

/* ── Types ───────────────────────────────────────────────────── */

export type CardVariant = "default" | "elevated" | "outlined" | "filled"
export type CardSize    = "sm" | "md" | "lg"

export interface CardProps {
  variant?:     CardVariant
  size?:        CardSize
  /** Adds hover, focus-visible, and cursor:pointer styles */
  interactive?: boolean
  /** Shows primary border + subtle bg; use aria-pressed/aria-selected on caller */
  selected?:    boolean
  /** Suppresses interaction; applies opacity-disabled */
  disabled?:    boolean
  onClick?:     React.MouseEventHandler<HTMLElement>
  className?:   string
  children?:    React.ReactNode
  id?:          string
}

/* ── Card root ───────────────────────────────────────────────── */

export function Card({
  variant     = "default",
  size        = "md",
  interactive = false,
  selected    = false,
  disabled    = false,
  onClick,
  className,
  children,
  id,
}: CardProps) {
  const generatedId = useId()
  const uid      = id ?? generatedId
  const titleId  = `${uid}-title`

  const classes = cx(
    styles.card,
    styles[variant],
    size !== "md" && styles[size],
    interactive && styles.interactive,
    selected    && styles.selected,
    disabled    && styles.disabled,
    className,
  )

  return (
    <CardContext.Provider value={{ titleId }}>
      {interactive ? (
        /*
         * BUG-030 — native <button> instead of <div role="button">.
         * Native button: implicit role="button", keyboard activation
         * (Enter + Space) built-in, correct type="button" default.
         * No manual onKeyDown needed.
         *
         * BUG-027/065 — aria-labelledby wired to CardTitle via context-
         * provided titleId so screen readers announce the card by its title.
         */
        <button
          id={uid}
          type="button"
          aria-labelledby={titleId}
          aria-disabled={disabled || undefined}
          aria-pressed={selected || undefined}
          onClick={disabled ? undefined : onClick}
          tabIndex={disabled ? -1 : 0}
          className={classes}
        >
          {children}
        </button>
      ) : (
        <article
          id={uid}
          aria-disabled={disabled || undefined}
          className={classes}
        >
          {children}
        </article>
      )}
    </CardContext.Provider>
  )
}

/* ── CardHeader ──────────────────────────────────────────────── */
/*
 * Layout: [leading] [main slot (children)] [action]
 * leading and action are optional slots at the inline edges.
 * children should be CardTitle + CardDescription.
 */

export interface CardHeaderProps {
  /** Inline-start slot — icon, avatar, or image */
  leading?:   React.ReactNode
  /** Inline-end slot — overflow menu, icon button */
  action?:    React.ReactNode
  className?: string
  children?:  React.ReactNode
}

export function CardHeader({ leading, action, className, children }: CardHeaderProps) {
  return (
    <div className={cx(styles.header, className)}>
      {leading && (
        <span className={styles.leading} aria-hidden="true">
          {leading}
        </span>
      )}

      <div className={styles.headerMain}>
        {children}
      </div>

      {action && (
        <span className={styles.action}>
          {action}
        </span>
      )}
    </div>
  )
}

/* ── CardTitle ───────────────────────────────────────────────── */
/*
 * BUG-029 — render as a semantic heading (h3 by default) instead of <p>.
 * The `as` prop allows callers to adjust the heading level to fit the
 * page's document outline without forcing a global level.
 *
 * BUG-027/065 — consumes CardContext to self-assign id={titleId},
 * enabling the interactive Card root's aria-labelledby reference.
 */

export interface CardTitleProps {
  /** Heading level — defaults to "h3" to match article landmark convention */
  as?:        "h1" | "h2" | "h3" | "h4" | "h5" | "h6"
  className?: string
  children?:  React.ReactNode
}

export function CardTitle({ as: As = "h3", className, children }: CardTitleProps) {
  const ctx = useContext(CardContext)
  return (
    <As
      id={ctx?.titleId}
      className={cx(styles.title, className)}
    >
      {children}
    </As>
  )
}

/* ── CardDescription ─────────────────────────────────────────── */

export interface CardDescriptionProps {
  className?: string
  children?:  React.ReactNode
}

export function CardDescription({ className, children }: CardDescriptionProps) {
  return (
    <p className={cx(styles.description, className)}>
      {children}
    </p>
  )
}

/* ── CardContent ─────────────────────────────────────────────── */

export interface CardContentProps {
  className?: string
  children?:  React.ReactNode
}

export function CardContent({ className, children }: CardContentProps) {
  return (
    <div className={cx(styles.content, className)}>
      {children}
    </div>
  )
}

/* ── CardFooter ──────────────────────────────────────────────── */

export interface CardFooterProps {
  /** Alignment of footer children: start (default) | between | end */
  justify?:   "start" | "between" | "end"
  className?: string
  children?:  React.ReactNode
}

export function CardFooter({ justify = "start", className, children }: CardFooterProps) {
  const justifyClass =
    justify === "between" ? styles.footerBetween :
    justify === "end"     ? styles.footerEnd :
    undefined

  return (
    <div className={cx(styles.footer, justifyClass, className)}>
      {children}
    </div>
  )
}

"use client"

/**
 * Atlas Badge — compact label for status, count, or category
 *
 * Variants:  default | secondary | success | warning | danger | info | outline
 * Sizes:     sm | md | lg
 * States:    default · hover (interactive only) · focus-visible (interactive only) · disabled
 *
 * Slots:
 *   dot          — 6px status circle at inline-start (color = currentColor)
 *   leadingIcon  — icon at inline-start (after dot)
 *   children     — label text (required)
 *   trailingIcon — icon at inline-end
 *   removable    — × close button at inline-end (makes badge interactive)
 *
 * Accessibility:
 *   - Non-interactive: <span>, decorative
 *   - Interactive (onClick): renders as <button> with data-interactive attr
 *   - Removable: close affordance is <button aria-label="Remove {label}">
 *   - Status/live: wrap badge in role="status" + aria-live="polite" at call site
 */

import React from "react"
import styles from "./Badge.module.css"

/* ── Types ──────────────────────────────────────────────────────── */

export type BadgeVariant = "default" | "secondary" | "success" | "warning" | "danger" | "info" | "outline"
export type BadgeSize    = "sm" | "md" | "lg"
export type BadgeIntent  = "default" | "success" | "warning" | "danger" | "info"

export interface BadgeProps {
  variant?:      BadgeVariant
  size?:         BadgeSize
  /**
   * Only used with `variant="outline"`.
   * Colors the border and text to match the intent semantic color.
   */
  intent?:       BadgeIntent
  /** Uses --atlas-radius-sm instead of radius-full */
  square?:       boolean
  /** Leading 6px status dot; color inherits from variant foreground */
  dot?:          boolean
  leadingIcon?:  React.ReactNode
  trailingIcon?: React.ReactNode
  /** Adds a × button at inline-end; onRemove fires when clicked */
  removable?:    boolean
  onRemove?:     () => void
  /**
   * Explicit accessible label for the remove button.
   * Required when `removable=true` and `children` is not a plain string.
   * Falls back to children string content; ultimate fallback is "item".
   * FIX BUG-024
   */
  removeLabel?:  string
  /**
   * Makes the entire badge a pressable surface.
   * Renders as <button> when provided; <span> otherwise.
   * FIX BUG-023
   */
  onClick?:      () => void
  disabled?:     boolean
  className?:    string
  children:      React.ReactNode
}

/* ── Helpers ────────────────────────────────────────────────────── */

function cx(...classes: (string | false | null | undefined)[]): string {
  return classes.filter(Boolean).join(" ")
}

/* ── Component ──────────────────────────────────────────────────── */

export function Badge({
  variant     = "default",
  size        = "md",
  intent      = "default",
  square      = false,
  dot         = false,
  leadingIcon,
  trailingIcon,
  removable   = false,
  onRemove,
  removeLabel,
  onClick,
  disabled    = false,
  className,
  children,
}: BadgeProps) {
  /* Intent class only applies on outline variant */
  const intentClass =
    variant === "outline" && intent !== "default"
      ? styles[`intent${intent.charAt(0).toUpperCase()}${intent.slice(1)}` as keyof typeof styles]
      : undefined

  const isInteractive = Boolean(onClick)

  const classes = cx(
    styles.badge,
    styles[variant],
    styles[size],
    square   && styles.square,
    disabled && styles.disabled,
    intentClass,
    className,
  )

  /* Derive label string for the remove button aria-label — FIX BUG-024 */
  const labelText = removeLabel ?? (typeof children === "string" ? children : undefined)

  if (
    process.env.NODE_ENV !== "production" &&
    removable &&
    !labelText
  ) {
    console.warn(
      "[Atlas Badge] removable=true requires either a string `children` or an explicit `removeLabel` prop " +
      "to produce an accessible aria-label for the remove button."
    )
  }

  const content = (
    <>
      {/* Leading status dot — color inherits currentColor from variant */}
      {dot && <span className={styles.dot} aria-hidden="true" />}

      {/* Leading icon slot */}
      {leadingIcon && (
        <span aria-hidden="true">{leadingIcon}</span>
      )}

      {/* Label */}
      {children}

      {/* Trailing icon slot (hidden when removable — remove button takes that position) */}
      {!removable && trailingIcon && (
        <span aria-hidden="true">{trailingIcon}</span>
      )}

      {/* Remove affordance */}
      {removable && (
        <button
          type="button"
          className={styles.removeBtn}
          aria-label={`Remove ${labelText ?? "item"}`}
          onClick={(e) => {
            e.stopPropagation()
            onRemove?.()
          }}
          disabled={disabled}
          tabIndex={disabled ? -1 : 0}
        >
          {/* FIX BUG-067: aria-hidden prevents double-announcement ("Remove item times") */}
          <span aria-hidden="true">×</span>
        </button>
      )}
    </>
  )

  /* FIX BUG-023: render <button> when onClick is provided */
  if (isInteractive) {
    return (
      <button
        type="button"
        className={classes}
        data-interactive
        onClick={disabled ? undefined : onClick}
        disabled={disabled}
        aria-disabled={disabled || undefined}
      >
        {content}
      </button>
    )
  }

  return (
    <span className={classes}>
      {content}
    </span>
  )
}

"use client"

/**
 * Atlas Button — canonical reference component
 *
 * Variants:  primary | secondary | outline | ghost | destructive | link
 * Sizes:     sm | md | lg | icon
 * States:    default · hover · focus-visible · active · disabled · loading
 *
 * Accessibility:
 *   - aria-busy="true" when loading (async in progress)
 *   - aria-disabled="true" when disabled or loading
 *   - aria-label required by caller when size="icon"
 *   - Focus ring via CSS :focus-visible; never suppressed
 *
 * Logical properties and prefers-reduced-motion handled in Button.module.css.
 */

import React from "react"
import { Slot } from "@radix-ui/react-slot"
import styles from "./Button.module.css"

/* ── Types ──────────────────────────────────────────────── */

export type ButtonVariant =
  | "primary"
  | "secondary"
  | "outline"
  | "ghost"
  | "destructive"
  | "link"

export type ButtonSize = "sm" | "md" | "lg" | "icon"

export interface ButtonProps
  extends React.ButtonHTMLAttributes<HTMLButtonElement> {
  variant?: ButtonVariant
  /**
   * Size of the button.
   * - `sm | md | lg` — named heights (32 / 40 / 48 px).
   * - `icon` — legacy alias for `md` + `iconOnly`. Kept for back-compat.
   *   Prefer explicit `size="md" iconOnly` for new callers.
   */
  size?: ButtonSize
  /**
   * When true, collapses padding to zero and clamps width = height so the
   * button becomes a square icon-only control.
   * Composes with `size` — e.g. `size="lg" iconOnly` gives a 48 × 48 button.
   * Requires `aria-label` or `aria-labelledby` (dev-mode warning fired if absent).
   */
  iconOnly?: boolean
  loading?: boolean
  leadingIcon?: React.ReactNode
  trailingIcon?: React.ReactNode
  /**
   * Web only — Radix Slot pattern.
   * Renders styles onto the child element instead of a <button>.
   * Useful for wrapping <a> tags with button styles.
   */
  asChild?: boolean
  children?: React.ReactNode
}

/* ── Helpers ────────────────────────────────────────────── */

/** Minimal class-name joiner — no external dependency. */
function cx(...classes: (string | false | null | undefined)[]): string {
  return classes.filter(Boolean).join(" ")
}

/* ── Component ──────────────────────────────────────────── */

export function Button({
  variant = "primary",
  size = "md",
  iconOnly = false,
  loading = false,
  leadingIcon,
  trailingIcon,
  asChild = false,
  children,
  disabled,
  className,
  onClick,
  type = "button",
  ...rest
}: ButtonProps) {
  const Comp = (asChild ? Slot : "button") as React.ElementType

  /*
   * BUG-005 fix: resolve effective size and icon-only modifier independently.
   *
   * `size="icon"` is a legacy alias: it maps to `md` height + square layout.
   * New callers should use `size="sm|md|lg" iconOnly` for composable control.
   *
   * effectiveSize — always one of sm | md | lg; drives the height/padding class.
   * isIconOnly    — when true, applies the .icon modifier (padding:0, width=height).
   */
  const effectiveSize: "sm" | "md" | "lg" = size === "icon" ? "md" : size
  const isIconOnly = size === "icon" || iconOnly

  /*
   * BUG-006 fix: fire a dev-mode warning when an icon-only button has no
   * accessible label. Screen readers have no text to announce otherwise.
   */
  if (
    process.env.NODE_ENV !== "production" &&
    isIconOnly &&
    !rest["aria-label"] &&
    !rest["aria-labelledby"]
  ) {
    console.warn(
      "[Atlas Button] Icon-only buttons (size='icon' or iconOnly=true) require " +
      "an aria-label or aria-labelledby prop for screen reader accessibility.",
    )
  }

  /**
   * Size class is omitted for the link variant: links are inline elements
   * with no fixed height. The .link CSS class zeroes padding-inline and
   * resets border-radius, so applying a size class would conflict.
   */
  const classes = cx(
    styles.btn,
    styles[variant],
    variant !== "link" ? styles[effectiveSize] : undefined,
    isIconOnly ? styles.icon : undefined,
    className,
  )

  /**
   * Interaction guard:
   *   - Native `disabled` attr  → only when prop `disabled` is true
   *                               (preserves tab-stop during loading)
   *   - aria-disabled            → true when disabled OR loading
   *   - aria-busy                → true only when loading
   *   - onClick                  → suppressed when disabled or loading
   *
   * We do NOT set the native `disabled` attr when loading so the button
   * remains keyboard-focusable and screen readers can announce aria-busy.
   * pointer-events: none on [aria-disabled="true"] in the CSS module
   * prevents mouse clicks without removing focus.
   */
  const isAriaDisabled = disabled || loading || undefined // undefined removes attr

  return (
    <Comp
      /* Caller props spread first so our controlled attrs always win */
      {...rest}
      /* native type only applies to real <button>; Slot forwards to child */
      type={asChild ? undefined : type}
      className={classes}
      disabled={disabled}
      aria-disabled={isAriaDisabled}
      aria-busy={loading || undefined}
      onClick={disabled || loading ? undefined : onClick}
    >
      {/* Leading icon slot — replaced by spinner when loading */}
      {loading ? (
        <span
          className={styles.spinner}
          aria-hidden="true" /* spinner is decorative; aria-busy conveys state */
        />
      ) : (
        leadingIcon
      )}

      {children}

      {/* Trailing icon: visibility:hidden while loading preserves its layout
          width so the button doesn't reflow between states. */}
      {trailingIcon && (
        <span
          className={loading ? styles.trailingHidden : undefined}
          aria-hidden={loading ? "true" : undefined}
        >
          {trailingIcon}
        </span>
      )}
    </Comp>
  )
}

"use client"

/**
 * Atlas Alert — inline status/feedback message
 *
 * Variants:  info | success | warning | danger
 * Sizes:     sm | md
 *
 * Anatomy:
 *   [accent bar] [icon] [body: title · description · actions] [dismiss ×]
 *
 * Accessibility:
 *   - role="status" (polite)    for info/success
 *   - role="alert"  (assertive) for warning/danger
 *   - Dismiss button: <button aria-label="Dismiss [variant] alert">
 *   - Dismiss touch target ≥ --atlas-touch-min (44px)
 *   - Reduced motion: enter + exit animations suppressed via CSS media query
 *
 * Props:
 *   title       — bold first line (optional)
 *   description — body text (optional; alias: children)
 *   icon        — override default intent icon
 *   hideIcon    — suppress icon entirely
 *   actions     — slot for inline <Button> elements
 *   dismissible — shows × button
 *   onDismiss   — fires after exit animation completes (FIX BUG-032)
 */

import React, { useState, useEffect } from "react"
import styles from "./Alert.module.css"

/* ── Types ──────────────────────────────────────────────────────── */

export type AlertVariant = "info" | "success" | "warning" | "danger"
export type AlertSize    = "sm" | "md"

export interface AlertProps {
  variant?:     AlertVariant
  size?:        AlertSize
  title?:       React.ReactNode
  /** Description text. Alternatively pass as children. */
  description?: React.ReactNode
  /** Override the default intent icon */
  icon?:        React.ReactNode
  /** Hide the leading icon entirely */
  hideIcon?:    boolean
  /** Slot for inline action buttons below the description */
  actions?:     React.ReactNode
  /** Show the × dismiss button */
  dismissible?: boolean
  /**
   * Fires after the exit animation completes.
   * Use to unmount the Alert in the parent (do not unmount immediately on click).
   * FIX BUG-032
   */
  onDismiss?:   () => void
  className?:   string
  /** Description content (alias for description prop) */
  children?:    React.ReactNode
}

/* ── Helpers ────────────────────────────────────────────────────── */

function cx(...classes: (string | false | null | undefined)[]): string {
  return classes.filter(Boolean).join(" ")
}

/* Detect reduced-motion preference at runtime for instant dismiss fallback */
function prefersReducedMotion(): boolean {
  if (typeof window === "undefined") return false
  return window.matchMedia("(prefers-reduced-motion: reduce)").matches
}

/* ── Default icons per variant ──────────────────────────────────── */

const DEFAULT_ICONS: Record<AlertVariant, string> = {
  info:    "ℹ",
  success: "✓",
  warning: "⚠",
  danger:  "⊗",
}

/* ── Component ──────────────────────────────────────────────────── */

export function Alert({
  variant     = "info",
  size        = "md",
  title,
  description,
  icon,
  hideIcon    = false,
  actions,
  dismissible = false,
  onDismiss,
  className,
  children,
}: AlertProps) {
  /* FIX BUG-032: track dismissing state to run exit animation */
  const [isDismissing, setIsDismissing] = useState(false)

  /* role follows intent severity */
  const role = variant === "warning" || variant === "danger" ? "alert" : "status"

  /* description — prefer explicit prop, fall back to children */
  const descContent = description ?? children

  /* icon — prefer override, fall back to default */
  const iconContent = icon ?? DEFAULT_ICONS[variant]

  const classes = cx(
    styles.alert,
    styles[variant],
    size !== "md" && styles[size],
    isDismissing && styles.dismissing,
    className,
  )

  /* FIX BUG-032: trigger exit animation; under reduced-motion, call onDismiss immediately */
  const handleDismiss = () => {
    if (prefersReducedMotion()) {
      onDismiss?.()
      return
    }
    setIsDismissing(true)
  }

  /* FIX BUG-032: after exit animation ends, notify parent to unmount */
  const handleAnimationEnd = (e: React.AnimationEvent<HTMLDivElement>) => {
    // Only respond to the alertExit animation, not alertEnter
    if (isDismissing && e.animationName.includes("alertExit")) {
      onDismiss?.()
    }
  }

  return (
    <div
      role={role}
      className={classes}
      onAnimationEnd={isDismissing ? handleAnimationEnd : undefined}
    >
      {/* Leading icon */}
      {!hideIcon && (
        <span className={styles.icon} aria-hidden="true">
          {iconContent}
        </span>
      )}

      {/* Body */}
      <div className={styles.body}>
        {title && (
          <p className={styles.title}>{title}</p>
        )}
        {descContent && (
          <p className={styles.description}>{descContent}</p>
        )}
        {actions && (
          <div className={styles.actions}>{actions}</div>
        )}
      </div>

      {/* Dismiss */}
      {dismissible && (
        <button
          type="button"
          className={styles.dismissBtn}
          aria-label={`Dismiss ${variant} alert`}
          onClick={handleDismiss}
          disabled={isDismissing}
        >
