 */

export type Recipient = {
  id: string
  name: string
  /** Masked account number, e.g. "•••• 4471" */
  maskedAccount: string
  currency: string
  /** Emoji avatar / flag shown in the recipient list */
  avatar: string
}

export const RECENT_RECIPIENTS: Recipient[] = [
  { id: "r1", name: "Amara Okafor", maskedAccount: "•••• 4471", currency: "NGN", avatar: "🇳🇬" },
  { id: "r2", name: "Diego Fernández", maskedAccount: "•••• 8823", currency: "EUR", avatar: "🇪🇸" },
  { id: "r3", name: "Priya Nair", maskedAccount: "•••• 1190", currency: "INR", avatar: "🇮🇳" },
  { id: "r4", name: "Tom Whitfield", maskedAccount: "•••• 5567", currency: "GBP", avatar: "🇬🇧" },
  { id: "r5", name: "Mei Ling Tan", maskedAccount: "•••• 3302", currency: "SGD", avatar: "🇸🇬" },
]

/** Fixed source currency for this prototype — the "You send" side */
export const SOURCE_CURRENCY = "USD"

/** Indicative FX rate USD -> recipient currency, and fee rate, per currency */
export const FX_RATES: Record<string, number> = {
  NGN: 1538.42,
  EUR: 0.9235,
  INR: 83.12,
  GBP: 0.7841,
  SGD: 1.3452,
}

export const FEE_FLAT = 1.99
export const FEE_RATE = 0.005 // 0.5%

export type SendMoneyData = {
  recipient: Recipient | null
  recipientQuery: string
  amount: string
  confirmed: boolean
}

export const SEND_MONEY_INITIAL: SendMoneyData = {
  recipient: null,
  recipientQuery: "",
  amount: "",
  confirmed: false,
}

export const SEND_MONEY_STEPS = ["recipient", "amount", "review"] as const

export type SendMoneyStepKey = (typeof SEND_MONEY_STEPS)[number]

/** Props every Send Money step receives */
export type SendMoneyStepProps = {
  data: SendMoneyData
  patch: (partial: Partial<SendMoneyData>) => void
  next: () => void
  back: () => void
  goTo: (index: number) => void
}

/** Computes the fee, converted amount, and total for a given "you send" amount */
export function computeQuote(amountStr: string, currency: string) {
  const amount = parseFloat(amountStr)
  if (!currency || !Number.isFinite(amount) || amount <= 0) {
    return { amount: 0, fee: 0, total: 0, rate: 0, recipientGets: 0, valid: false }
  }
  const rate = FX_RATES[currency] ?? 1
  const fee = Math.round((FEE_FLAT + amount * FEE_RATE) * 100) / 100
  const total = Math.round((amount + fee) * 100) / 100
  const recipientGets = Math.round(amount * rate * 100) / 100
  return { amount, fee, total, rate, recipientGets, valid: true }
}

