"use client"

import React from "react"

/**
 * Shared screen chrome for Send Money step screens — a thin header row
 * with optional back affordance and a title.
 */
export function ScreenHeader({
  title,
  onBack,
}: {
  title: string
  onBack?: () => void
}) {
  return (
    <div
      style={{
        display: "flex",
        alignItems: "center",
        gap: "var(--atlas-spacing-3)",
        height: 44,
      }}
    >
      {onBack && (
        <button
          type="button"
          aria-label="Back"
          onClick={onBack}
          style={iconBtnStyle}
        >
          <svg width="18" height="18" viewBox="0 0 24 24" fill="none" aria-hidden>
            <path
              d="M15 18l-6-6 6-6"
              stroke="currentColor"
              strokeWidth="2"
              strokeLinecap="round"
              strokeLinejoin="round"
            />
          </svg>
        </button>
      )}
      <strong style={{ fontSize: "var(--atlas-font-size-lg)" }}>{title}</strong>
    </div>
  )
}

const iconBtnStyle: React.CSSProperties = {
  width: 36,
  height: 36,
  display: "inline-flex",
  alignItems: "center",
  justifyContent: "center",
  background: "transparent",
  border: 0,
  cursor: "pointer",
  color: "var(--atlas-foreground)",
  borderRadius: "var(--atlas-radius-full)",
  flexShrink: 0,
}

