"use client"

import React, { useMemo } from "react"
import { Input } from "@atlas/ui-web/primitives/Input/Input"
import { Card, CardContent } from "@atlas/ui-web/compositions/Card/Card"
import { Badge } from "@atlas/ui-web/primitives/Badge/Badge"
import { RECENT_RECIPIENTS, SendMoneyStepProps } from "../schema"
import { ScreenHeader } from "./_chrome"

export function Recipient({ data, patch, next }: SendMoneyStepProps) {
  const query = data.recipientQuery.trim().toLowerCase()

  const filtered = useMemo(() => {
    if (!query) return RECENT_RECIPIENTS
    return RECENT_RECIPIENTS.filter((r) => r.name.toLowerCase().includes(query))
  }, [query])

  const handleSelect = (id: string) => {
    const recipient = RECENT_RECIPIENTS.find((r) => r.id === id) ?? null
    patch({ recipient })
    next()
  }

  return (
    <div
      style={{
        flex: 1,
        display: "flex",
        flexDirection: "column",
        padding: "var(--atlas-spacing-3) var(--atlas-spacing-5) var(--atlas-spacing-5)",
        overflowY: "auto",
      }}
    >
      <ScreenHeader title="Send money" />

      <p
        style={{
          margin: "var(--atlas-spacing-2) 0 0",
          fontSize: "var(--atlas-font-size-sm)",
          color: "var(--atlas-foreground-muted)",
        }}
      >
        Who are you sending to?
      </p>

      <div style={{ marginBlockStart: "var(--atlas-spacing-4)" }}>
        <Input
          aria-label="Search recipients"
          placeholder="Search by name"
          leadingIcon={<span aria-hidden style={{ fontSize: 14 }}>🔍</span>}
          value={data.recipientQuery}
          onChange={(e) => patch({ recipientQuery: e.target.value })}
        />
      </div>

      <div
        style={{
          marginBlockStart: "var(--atlas-spacing-5)",
          fontSize: "var(--atlas-font-size-xs)",
          fontWeight: 600,
          color: "var(--atlas-foreground-muted)",
          textTransform: "uppercase",
          letterSpacing: "0.04em",
        }}
      >
        Recent recipients
      </div>

      <div
        style={{
          display: "flex",
          flexDirection: "column",
          gap: "var(--atlas-spacing-2)",
          marginBlockStart: "var(--atlas-spacing-3)",
        }}
      >
        {filtered.map((r) => (
          <Card
            key={r.id}
            variant="outlined"
            size="sm"
            interactive
            onClick={() => handleSelect(r.id)}
          >
            <CardContent>
              <div style={{ display: "flex", alignItems: "center", gap: "var(--atlas-spacing-3)" }}>
                <span
                  aria-hidden
                  style={{
                    fontSize: 22,
                    width: 40,
                    height: 40,
                    display: "flex",
                    alignItems: "center",
                    justifyContent: "center",
                    borderRadius: "var(--atlas-radius-full)",
                    background: "var(--atlas-background-muted)",
                    flexShrink: 0,
                  }}
                >
                  {r.avatar}
                </span>
                <div style={{ flex: 1, textAlign: "left" }}>
                  <div style={{ fontSize: "var(--atlas-font-size-sm)", fontWeight: 600 }}>
                    {r.name}
                  </div>
                  <div
                    style={{
                      fontSize: "var(--atlas-font-size-xs)",
                      color: "var(--atlas-foreground-muted)",
                    }}
                  >
                    {r.maskedAccount}
                  </div>
                </div>
                <Badge size="sm" variant="secondary">
                  {r.currency}
                </Badge>
              </div>
            </CardContent>
          </Card>
        ))}

        {filtered.length === 0 && (
          <p
            style={{
              margin: "var(--atlas-spacing-4) 0",
              fontSize: "var(--atlas-font-size-sm)",
              color: "var(--atlas-foreground-muted)",
              textAlign: "center",
            }}
          >
            No recipients match &ldquo;{data.recipientQuery}&rdquo;
          </p>
        )}
      </div>
    </div>
  )
}

