input.content:
"use client"

import React, { useState } from "react"
import { Button } from "@atlas/ui-web/primitives/Button/Button"
import { Badge } from "@atlas/ui-web/primitives/Badge/Badge"
import {
  Dialog,
  DialogContent,
  DialogHeader,
  DialogTitle,
  DialogDescription,
  DialogBody,
  DialogFooter,
  DialogClose,
} from "@atlas/ui-web/compositions/Dialog/Dialog"
import { computeQuote, SendMoneyStepProps, SOURCE_CURRENCY } from "../schema"
import { mockSubmit } from "../../_shared/mockApi"
import { ScreenHeader } from "./_chrome"

export function Review({ data, patch, back, goTo }: SendMoneyStepProps) {
  const [confirmOpen, setConfirmOpen] = useState(false)
  const [sending, setSending] = useState(false)

  const currency = data.recipient?.currency ?? SOURCE_CURRENCY
  const quote = computeQuote(data.amount, currency)

  const handleConfirm = async () => {
    setSending(true)
    try {
      await mockSubmit({ ...data }, { delayMs: 1200 })
      patch({ confirmed: true })
    } finally {
      setSending(false)
    }
  }

  if (data.confirmed) {
    return (
      <div
        style={{
          flex: 1,
          display: "flex",
          flexDirection: "column",
          alignItems: "center",
          justifyContent: "center",
          padding: "var(--atlas-spacing-5)",
          textAlign: "center",
          gap: "var(--atlas-spacing-4)",
        }}
      >
        <div
          aria-hidden
          style={{
            width: 72,
            height: 72,
            borderRadius: "var(--atlas-radius-full)",
            background: "var(--atlas-success-subtle)",
            color: "var(--atlas-success)",
            display: "flex",
            alignItems: "center",
            justifyContent: "center",
            fontSize: 36,
          }}
        >
          ✓
        </div>
        <div>
          <h1 style={{ margin: 0, fontSize: "var(--atlas-font-size-xl)", fontWeight: 700 }}>
            Money is on its way
          </h1>
          <p
            style={{
              margin: "var(--atlas-spacing-2) 0 0",
              fontSize: "var(--atlas-font-size-sm)",
              color: "var(--atlas-foreground-muted)",
            }}
          >
            {data.recipient?.name} will get {currency} {quote.recipientGets.toFixed(2)}
          </p>
        </div>
        <Badge size="sm" variant="success" dot>
          Transfer confirmed
        </Badge>
        <Button variant="outline" size="sm" onClick={() => goTo(0)}>
          Send another payment
        </Button>
      </div>
    )
  }

  return (
    <div
      style={{
        flex: 1,
        display: "flex",
        flexDirection: "column",
        padding: "var(--atlas-spacing-3) var(--atlas-spacing-5) var(--atlas-spacing-5)",
        overflowY: "auto",
      }}
    >
      <ScreenHeader title="Review transfer" onBack={back} />

      {/* Recipient summary */}
      <div
        style={{
          marginBlockStart: "var(--atlas-spacing-5)",
          display: "flex",
          alignItems: "center",
          gap: "var(--atlas-spacing-3)",
        }}
      >
        <span
          aria-hidden
          style={{
            fontSize: 22,
            width: 40,
            height: 40,
            display: "flex",
            alignItems: "center",
            justifyContent: "center",
            borderRadius: "var(--atlas-radius-full)",
            background: "var(--atlas-background-muted)",
            flexShrink: 0,
          }}
        >
          {data.recipient?.avatar}
        </span>
        <div>
          <div style={{ fontSize: "var(--atlas-font-size-base)", fontWeight: 600 }}>
            {data.recipient?.name}
          </div>
          <div style={{ fontSize: "var(--atlas-font-size-xs)", color: "var(--atlas-foreground-muted)" }}>
            {data.recipient?.maskedAccount}
          </div>
        </div>
      </div>

      {/* Amount + fee summary */}
      <div
        style={{
          marginBlockStart: "var(--atlas-spacing-5)",
          padding: "var(--atlas-spacing-3) var(--atlas-spacing-4)",
          borderRadius: "var(--atlas-radius-md)",
          background: "var(--atlas-background-muted)",
          display: "flex",
          flexDirection: "column",
          gap: "var(--atlas-spacing-2)",
        }}
      >
        <Row label="You send" value={`${SOURCE_CURRENCY} ${quote.amount.toFixed(2)}`} />
        <Row label="Our fee" value={`${SOURCE_CURRENCY} ${quote.fee.toFixed(2)}`} />
        <Row label="Recipient gets" value={`${currency} ${quote.recipientGets.toFixed(2)}`} strong />
        <Row label="Total to pay" value={`${SOURCE_CURRENCY} ${quote.total.toFixed(2)}`} strong />
      </div>

      <div style={{ flex: 1 }} />

      <Dialog open={confirmOpen} onOpenChange={setConfirmOpen}>
        <Button
          variant="primary"
          size="lg"
          onClick={() => setConfirmOpen(true)}
          style={{ width: "100%" }}
        >
          Confirm and send
        </Button>

        <DialogContent size="sm">
          <DialogHeader>
            <DialogTitle>Confirm transfer</DialogTitle>
            <DialogDescription>
              You&apos;re sending {SOURCE_CURRENCY} {quote.total.toFixed(2)} (total) to{" "}
              {data.recipient?.name}. This can&apos;t be undone.
            </DialogDescription>
          </DialogHeader>
          <DialogBody>
            <Row label="Recipient gets" value={`${currency} ${quote.recipientGets.toFixed(2)}`} strong />
          </DialogBody>
          <DialogFooter>
            <DialogClose asChild>
              <Button variant="outline">Cancel</Button>
            </DialogClose>
            <Button
              variant="primary"
              loading={sending}
              onClick={async () => {
                await handleConfirm()
                setConfirmOpen(false)
              }}
            >
              Send now
            </Button>
          </DialogFooter>
        </DialogContent>
      </Dialog>
    </div>
  )
}

function Row({ label, value, strong }: { label: string; value: string; strong?: boolean }) {
  return (
    <div style={{ display: "flex", justifyContent: "space-between", alignItems: "center" }}>
      <span
        style={{
          fontSize: "var(--atlas-font-size-sm)",
          color: "var(--atlas-foreground-muted)",
        }}
      >
        {label}
      </span>
      <span
        style={{
          fontSize: "var(--atlas-font-size-sm)",
          fontWeight: strong ? 700 : 500,
          color: "var(--atlas-foreground)",
        }}
      >
        {value}
      </span>
    </div>
  )
}

