"use client"

import React, { useState } from "react"
import { Button } from "@atlas/ui-web/primitives/Button/Button"
import { Badge } from "@atlas/ui-web/primitives/Badge/Badge"
import {
  Dialog,
  DialogContent,
  DialogHeader,
  DialogTitle,
  DialogDescription,
  DialogBody,
  DialogFooter,
  DialogClose,
} from "@atlas/ui-web/compositions/Dialog/Dialog"
import { computeQuote, SendMoneyStepProps, SOURCE_CURRENCY } from "../schema"
import { mockSubmit } from "../../_shared/mockApi"
import { ScreenHeader } from "./_chrome"

export function Review({ data, patch, back, goTo }: SendMoneyStepProps) {
  const [confirmOpen, setConfirmOpen] = useState(false)
  const [sending, setSending] = useState(false)

  const currency = data.recipient?.currency ?? SOURCE_CURRENCY
  const quote = computeQuote(data.amount, currency)

  const handleConfirm = async () => {
    setSending(true)
    try {
      await mockSubmit({ ...data }, { delayMs: 1200 })
      patch({ confirmed: true })
    } finally {
      setSending(false)
    }
  }

  if (data.confirmed) {
    return (
      <div
        style={{
          flex: 1,
          display: "flex",
          flexDirection: "column",
          alignItems: "center",
          justifyContent: "center",
          padding: "var(--atlas-spacing-5)",
          textAlign: "center",
          gap: "var(--atlas-spacing-4)",
        }}
      >
        <div
          aria-hidden
          style={{
            width: 72,
            height: 72,
            borderRadius: "var(--atlas-radius-full)",
            background: "var(--atlas-success-subtle)",
            color: "var(--atlas-success)",
            display: "flex",
            alignItems: "center",
            justifyContent: "center",
            fontSize: 36,
          }}
        >
          ✓
        </div>
        <div>
          <h1 style={{ margin: 0, fontSize: "var(--atlas-font-size-xl)", fontWeight: 700 }}>
            Money is on its way
